Here's a minimal API endpoint that accepts multiple image files plus a text description via multipart form data:

```csharp
// Program.cs

var builder = WebApplication.CreateBuilder(args);

// Increase the max request body size to 50 MB
builder.WebHost.ConfigureKestrel(options =>
{
    options.Limits.MaxRequestBodySize = 50 * 1024 * 1024;
});

var app = builder.Build();

app.MapPost("/upload", async (HttpRequest request) =>
{
    // Read the multipart form with a 50 MB limit
    var form = await request.ReadFormAsync(new FormOptions
    {
        MultipartBodyLengthLimit = 50 * 1024 * 1024
    });

    var description = form["description"].ToString();
    var files = form.Files.GetFiles("images");

    if (files.Count == 0)
        return Results.BadRequest("No image files provided.");

    var uploaded = new List<string>();

    foreach (var file in files)
    {
        // Validate content type
        if (!file.ContentType.StartsWith("image/"))
            return Results.BadRequest($"'{file.FileName}' is not an image.");

        var savePath = Path.Combine("uploads", file.FileName);
        Directory.CreateDirectory("uploads");

        await using var stream = File.Create(savePath);
        await file.CopyToAsync(stream);

        uploaded.Add(file.FileName);
    }

    return Results.Ok(new { description, fileCount = uploaded.Count, uploaded });
})
.DisableAntiforgery();   // Required for form POSTs without antiforgery tokens

app.Run();
```

**Key points:**

- `ConfigureKestrel` raises the request body cap (defaults to ~28 MB).
- `FormOptions.MultipartBodyLengthLimit` controls the per-form limit.
- `DisableAntiforgery()` is needed in .NET 8 for unauthenticated form endpoints.
- The form field names (`description`, `images`) match what the client sends — e.g.:

```bash
curl -F "description=My photos" \
     -F "images=@photo1.jpg" \
     -F "images=@photo2.png" \
     http://localhost:5000/upload
```

For production you'd want to sanitize file names, store to a safe location (or blob storage), and add size-per-file validation.
